process.env.LOCAL_LAB_RELAY_ENABLED='0';
import {mock} from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,mkdir,writeFile,readFile,rm,stat} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {setTimeout as delay} from 'node:timers/promises';
